#include <iostream>
#include <string>

int main() {
    // یه متغیر رشته‌ای تعریف می‌کنیم
    std::string message = "ÇUKUR ON TOP";

    // چاپ پیام
    std::cout << "========================================" << std::endl;
    std::cout << "  Welcome to Simple C++ Program!" << std::endl;
    std::cout << "========================================" << std::endl;
    std::cout << std::endl;
    std::cout << "Message: " << message << std::endl;
    std::cout << std::endl;

    // یه حلقه ساده برای شمارش
    std::cout << "Counting from 1 to 5:" << std::endl;
    for (int i = 1; i <= 5; ++i) {
        std::cout << "  Number: " << i << std::endl;
    }

    std::cout << std::endl;
    std::cout << "Program finished successfully!" << std::endl;

    return 0;
}
